// ==========================================================
// VENDORIQ PERFORMANCE ANALYTICS
// Backend:
// GET /api/admin/performance/dashboard
//
// Response generated by:
// crud.build_performance_report()
//
// Expected response:
// {
//     success,
//     date_range,
//     filters,
//     kpis,
//     score_breakdown,
//     score_distribution,
//     performance_trend,
//     vendors,
//     categories,
//     insights
// }
// ==========================================================


"use strict";


// ==========================================================
// API CONFIGURATION
// ==========================================================

const API = "http://127.0.0.1:8000";


// ==========================================================
// CHART REFERENCES
// ==========================================================

let performanceChart = null;
let reliabilityChart = null;
let spendChart = null;


// ==========================================================
// REQUEST STATE
// ==========================================================

let dashboardLoading = false;


// ==========================================================
// AUTH TOKEN
// ==========================================================

function getAuthToken() {

    const tokenKeys = [
        "access_token",
        "token",
        "accessToken",
        "jwt_token"
    ];

    for (const key of tokenKeys) {

        const localToken =
            localStorage.getItem(key);

        if (localToken) {
            return localToken;
        }

        const sessionToken =
            sessionStorage.getItem(key);

        if (sessionToken) {
            return sessionToken;
        }
    }

    return null;
}


// ==========================================================
// API ERROR MESSAGE
// ==========================================================

function getApiErrorMessage(
    status,
    responseText
) {

    let message =
        `API request failed (${status}).`;

    if (!responseText) {
        return message;
    }

    try {

        const parsed =
            JSON.parse(responseText);

        if (typeof parsed.detail === "string") {
            return parsed.detail;
        }

        if (Array.isArray(parsed.detail)) {

            return parsed.detail
                .map(item =>
                    item.msg ||
                    item.message ||
                    String(item)
                )
                .join(", ");

        }

        if (parsed.message) {
            return String(parsed.message);
        }

    }
    catch (error) {

        // Response was not JSON.
        // Use the raw text below.

    }

    return `${message} ${responseText}`;
}


// ==========================================================
// API FETCH
// ==========================================================

async function apiFetch(
    url,
    options = {}
) {

    const token =
        getAuthToken();

    const headers = {
        "Accept": "application/json",
        ...(options.headers || {})
    };

    if (token) {

        headers["Authorization"] =
            `Bearer ${token}`;

    }

    const requestOptions = {
        ...options,
        headers
    };

    let response;

    try {

        response =
            await fetch(
                url,
                requestOptions
            );

    }
    catch (networkError) {

        throw new Error(
            "Unable to connect to the VendorIQ API. " +
            "Make sure FastAPI is running at " +
            API
        );

    }

    const responseText =
        await response.text();

    if (!response.ok) {

        throw new Error(
            getApiErrorMessage(
                response.status,
                responseText
            )
        );

    }

    if (!responseText.trim()) {
        return {};
    }

    try {

        return JSON.parse(
            responseText
        );

    }
    catch (parseError) {

        throw new Error(
            "The API returned invalid JSON."
        );

    }

}


// ==========================================================
// SAFE OBJECT
// ==========================================================

function safeObject(value) {

    if (
        value &&
        typeof value === "object" &&
        !Array.isArray(value)
    ) {

        return value;

    }

    return {};
}


// ==========================================================
// SAFE ARRAY
// ==========================================================

function safeArray(value) {

    return Array.isArray(value)
        ? value
        : [];

}


// ==========================================================
// SAFE NUMBER
// ==========================================================

function safeNumber(
    value,
    fallback = 0
) {

    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {

        return fallback;

    }

    const number =
        Number(value);

    return Number.isFinite(number)
        ? number
        : fallback;

}


// ==========================================================
// TEXT HELPER
// ==========================================================

function setText(
    elementId,
    value
) {

    const element =
        document.getElementById(
            elementId
        );

    if (element) {

        element.textContent =
            value ?? "";

    }

}


// ==========================================================
// HTML ESCAPE
// ==========================================================

function escapeHTML(value) {

    return String(
        value ?? ""
    )
    .replace(
        /&/g,
        "&amp;"
    )
    .replace(
        /</g,
        "&lt;"
    )
    .replace(
        />/g,
        "&gt;"
    )
    .replace(
        /"/g,
        "&quot;"
    )
    .replace(
        /'/g,
        "&#039;"
    );

}


// ==========================================================
// MONEY FORMAT
// ==========================================================

function formatMoney(value) {

    const number =
        safeNumber(value);

    if (Math.abs(number) >= 1000000000) {

        return "$" +
            (
                number / 1000000000
            ).toFixed(2) +
            "B";

    }

    if (Math.abs(number) >= 1000000) {

        return "$" +
            (
                number / 1000000
            ).toFixed(2) +
            "M";

    }

    if (Math.abs(number) >= 1000) {

        return "$" +
            (
                number / 1000
            ).toFixed(1) +
            "K";

    }

    return "$" +
        number.toLocaleString(
            "en-US",
            {
                maximumFractionDigits: 0
            }
        );

}


// ==========================================================
// PERCENT FORMAT
// ==========================================================

function formatPercent(
    value,
    decimals = 1
) {

    return safeNumber(
        value
    ).toFixed(decimals) + "%";

}


// ==========================================================
// DATE FORMAT
// ==========================================================

function formatDate(value) {

    if (!value) {
        return "—";
    }

    const date =
        new Date(value);

    if (
        Number.isNaN(
            date.getTime()
        )
    ) {

        return String(value);

    }

    return date.toLocaleDateString(
        "en-IN",
        {
            day: "2-digit",
            month: "short",
            year: "numeric"
        }
    );

}


// ==========================================================
// LOAD DASHBOARD
// ==========================================================

async function loadDashboard() {

    if (dashboardLoading) {
        return;
    }

    dashboardLoading = true;

    setLoadingState(true);

    try {

        console.log(
            "Loading VendorIQ Performance Analytics..."
        );

        const url =
            buildDashboardURL();

        console.log(
            "Performance API:",
            url
        );

        const data =
            await apiFetch(url);

        console.log(
            "Performance Analytics response:",
            data
        );

        const dashboard =
            safeObject(data);

        updateKPIs(
            dashboard
        );

        updateReliability(
            dashboard
        );

        updateTopVendors(
            dashboard
        );

        updateCategories(
            dashboard
        );

        updateScoreBreakdown(
            dashboard
        );

        updateInsights(
            dashboard
        );

        updatePerformanceChart(
            dashboard
        );

        updateSpendChart(
            dashboard
        );

        updateFooter(
            dashboard
        );

        updateDateRange(
            dashboard
        );

        clearError();

    }
    catch (error) {

        console.error(
            "Performance dashboard error:",
            error
        );

        showError(
            error.message ||
            "Unable to load performance analytics."
        );

    }
    finally {

        dashboardLoading = false;

        setLoadingState(false);

    }

}


// ==========================================================
// BUILD DASHBOARD URL
// ==========================================================
//
// The backend supports:
//
// ?from_date=YYYY-MM-DD
// ?to_date=YYYY-MM-DD
// ?category=...
// ?vendor_id=...
//
// If those filter elements do not exist in your HTML,
// nothing is added to the URL.
// ==========================================================

function buildDashboardURL() {

    const params =
        new URLSearchParams();

    const fromDate =
        getInputValue([
            "fromDate",
            "startDate",
            "from_date"
        ]);

    const toDate =
        getInputValue([
            "toDate",
            "endDate",
            "to_date"
        ]);

    const category =
        getInputValue([
            "categoryFilter",
            "category",
            "categorySelect"
        ]);

    const vendorId =
        getInputValue([
            "vendorFilter",
            "vendorSelect",
            "vendorId"
        ]);

    if (fromDate) {

        params.set(
            "from_date",
            fromDate
        );

    }

    if (toDate) {

        params.set(
            "to_date",
            toDate
        );

    }

    if (
        category &&
        category !== "All" &&
        category !== "All Categories"
    ) {

        params.set(
            "category",
            category
        );

    }

    if (vendorId) {

        params.set(
            "vendor_id",
            vendorId
        );

    }

    const query =
        params.toString();

    return query
        ? `${API}/api/admin/performance/dashboard?${query}`
        : `${API}/api/admin/performance/dashboard`;

}


// ==========================================================
// GET INPUT VALUE
// ==========================================================

function getInputValue(ids) {

    for (const id of ids) {

        const element =
            document.getElementById(id);

        if (!element) {
            continue;
        }

        const value =
            String(
                element.value ?? ""
            ).trim();

        if (value) {
            return value;
        }

    }

    return "";

}


// ==========================================================
// KPI UPDATE
// ==========================================================
//
// Actual backend:
// kpis.total_vendors
// kpis.overall_score
// kpis.on_time_delivery
// kpis.quality_score
// kpis.order_fulfillment
// kpis.response_time
// kpis.issue_resolution_time
// ==========================================================

function updateKPIs(data) {

    const kpis =
        safeObject(
            data.kpis
        );

    setText(
        "totalVendors",
        safeNumber(
            kpis.total_vendors
        ).toLocaleString()
    );

    setText(
        "avgReliability",
        safeNumber(
            kpis.overall_score
        ).toFixed(1)
    );

    setText(
        "onTimeDelivery",
        formatPercent(
            kpis.on_time_delivery
        )
    );

    setText(
        "qualityScore",
        formatPercent(
            kpis.quality_score
        )
    );

    setText(
        "totalSpend",
        "—"
    );

    setText(
        "savings",
        "—"
    );

    setText(
        "deliveryMini",
        formatPercent(
            kpis.on_time_delivery
        )
    );

    setText(
        "qualityMini",
        formatPercent(
            kpis.quality_score
        )
    );

    setText(
        "overallScore",
        safeNumber(
            kpis.overall_score
        ).toFixed(1)
    );

    setText(
        "orderFulfillment",
        formatPercent(
            kpis.order_fulfillment
        )
    );

    setText(
        "responseTime",
        safeNumber(
            kpis.response_time
        ).toFixed(1) + " hrs"
    );

    setText(
        "issueResolutionTime",
        safeNumber(
            kpis.issue_resolution_time
        ).toFixed(1) + " days"
    );

}


// ==========================================================
// SCORE DISTRIBUTION
// ==========================================================
//
// Actual backend returns:
//
// [
//     {
//         "label": "Excellent (90-100)",
//         "value": 5
//     },
//     ...
// ]
// ==========================================================

function updateReliability(data) {

    const distribution =
        safeArray(
            data.score_distribution
        );

    const total =
        distribution.reduce(
            (
                sum,
                item
            ) => {

                const row =
                    safeObject(item);

                return (
                    sum +
                    safeNumber(
                        row.value
                    )
                );

            },
            0
        );

    setText(
        "donutTotal",
        total.toLocaleString()
    );

    const list =
        document.getElementById(
            "distributionList"
        );

    if (list) {

        list.innerHTML = "";

        if (distribution.length === 0) {

            list.innerHTML = `
                <div class="empty-state">
                    No score distribution data available.
                </div>
            `;

        }
        else {

            const classes = [
                "green",
                "blue",
                "yellow",
                "orange",
                "red"
            ];

            distribution.forEach(
                (item, index) => {

                    const row =
                        safeObject(item);

                    const value =
                        safeNumber(
                            row.value
                        );

                    const percentage =
                        total > 0
                            ? (
                                value /
                                total *
                                100
                            ).toFixed(1)
                            : "0.0";

                    const element =
                        document.createElement(
                            "div"
                        );

                    element.className =
                        "distribution-row";

                    element.innerHTML = `

                        <span
                            class="distribution-dot ${
                                classes[
                                    index %
                                    classes.length
                                ]
                            }"
                        ></span>

                        <span>
                            ${escapeHTML(
                                row.label ||
                                "Unknown"
                            )}
                        </span>

                        <strong>
                            ${value}
                        </strong>

                        <span>
                            (${percentage}%)
                        </span>

                    `;

                    list.appendChild(
                        element
                    );

                }
            );

        }

    }


    renderReliabilityChart(
        distribution
    );

}


// ==========================================================
// RELIABILITY DONUT CHART
// ==========================================================

function renderReliabilityChart(
    distribution
) {

    const canvas =
        document.getElementById(
            "reliabilityChart"
        );

    if (!canvas) {
        return;
    }

    if (
        typeof Chart ===
        "undefined"
    ) {

        console.warn(
            "Chart.js is not loaded."
        );

        return;

    }

    const labels =
        distribution.map(
            item =>
                safeObject(
                    item
                ).label ||
                "Unknown"
        );

    const values =
        distribution.map(
            item =>
                safeNumber(
                    safeObject(
                        item
                    ).value
                )
        );

    if (reliabilityChart) {

        reliabilityChart.destroy();

        reliabilityChart =
            null;

    }

    const ctx =
        canvas.getContext(
            "2d"
        );

    if (!ctx) {
        return;
    }

    reliabilityChart =
        new Chart(
            ctx,
            {
                type: "doughnut",

                data: {

                    labels,

                    datasets: [
                        {
                            data: values,

                            backgroundColor: [
                                "#1caf73",
                                "#4389ee",
                                "#f5ad16",
                                "#ff7129",
                                "#ed414b"
                            ],

                            borderWidth: 2,

                            borderColor:
                                "#ffffff"
                        }
                    ]

                },

                options: {

                    responsive: true,

                    maintainAspectRatio:
                        false,

                    cutout: "65%",

                    plugins: {

                        legend: {
                            display: false
                        }

                    }

                }

            }
        );

}


// ==========================================================
// TOP VENDORS
// ==========================================================
//
// Actual backend field:
// data.vendors
//
// Each vendor:
// vendor_id
// vendor_name
// category
// overall_score
// on_time_delivery
// quality_score
// order_fulfillment
// response_time
// issue_resolution_time
// compliance_score
// communication_score
// trend
// ==========================================================

function updateTopVendors(data) {

    const container =
        document.getElementById(
            "topVendors"
        );

    if (!container) {
        return;
    }

    const vendors =
        safeArray(
            data.vendors
        )
        .slice()
        .sort(
            (
                a,
                b
            ) =>
                safeNumber(
                    safeObject(b).overall_score
                ) -
                safeNumber(
                    safeObject(a).overall_score
                )
        )
        .slice(0, 5);

    container.innerHTML = "";

    if (vendors.length === 0) {

        container.innerHTML = `
            <div class="empty-state">
                No vendor performance data available.
            </div>
        `;

        return;

    }

    vendors.forEach(
        (
            vendor,
            index
        ) => {

            vendor =
                safeObject(
                    vendor
                );

            const row =
                document.createElement(
                    "div"
                );

            row.className =
                "vendor-row";

            const trend =
                String(
                    vendor.trend ||
                    "flat"
                )
                .trim()
                .toLowerCase();

            let trendHTML =
                `<span class="trend-up">↑</span>`;

            if (
                trend.includes(
                    "down"
                )
            ) {

                trendHTML =
                    `<span class="trend-down">↓</span>`;

            }
            else if (
                trend.includes(
                    "flat"
                )
            ) {

                trendHTML =
                    `<span>→</span>`;

            }

            row.innerHTML = `

                <div>

                    <strong>
                        ${escapeHTML(
                            vendor.vendor_name ||
                            "Unknown Vendor"
                        )}
                    </strong>

                    <br>

                    <small>
                        ${escapeHTML(
                            vendor.category ||
                            "General"
                        )}
                    </small>

                </div>

                <div class="vendor-score">

                    ${safeNumber(
                        vendor.overall_score
                    ).toFixed(1)}/100

                </div>

                <div>
                    ${trendHTML}
                </div>

            `;

            container.appendChild(
                row
            );

        }
    );

}


// ==========================================================
// CATEGORY PERFORMANCE
// ==========================================================
//
// Actual backend:
// data.categories
//
// Each row:
// category
// on_time_delivery
// quality_score
// order_fulfillment
// overall_score
// ==========================================================

function updateCategories(data) {

    const container =
        document.getElementById(
            "categoryRows"
        );

    if (!container) {
        return;
    }

    const categories =
        safeArray(
            data.categories
        )
        .slice()
        .sort(
            (
                a,
                b
            ) =>
                safeNumber(
                    safeObject(b).overall_score
                ) -
                safeNumber(
                    safeObject(a).overall_score
                )
        );

    container.innerHTML = "";

    if (categories.length === 0) {

        container.innerHTML = `
            <div
                class="empty-state"
                style="font-size:12px;"
            >
                No category performance data available.
            </div>
        `;

        return;

    }

    categories
        .slice(0, 6)
        .forEach(
            category => {

                category =
                    safeObject(
                        category
                    );

                const row =
                    document.createElement(
                        "div"
                    );

                row.className =
                    "category-row";

                row.innerHTML = `

                    <span>
                        ${escapeHTML(
                            category.category ||
                            "General"
                        )}
                    </span>

                    <span>
                        ${formatPercent(
                            category.on_time_delivery
                        )}
                    </span>

                    <span>
                        ${formatPercent(
                            category.quality_score
                        )}
                    </span>

                    <span>
                        ${formatPercent(
                            category.order_fulfillment
                        )}
                    </span>

                    <span>
                        ${safeNumber(
                            category.overall_score
                        ).toFixed(1)}/100
                    </span>

                `;

                container.appendChild(
                    row
                );

            }
        );

}


// ==========================================================
// SCORE BREAKDOWN
// ==========================================================
//
// Actual backend:
//
// [
//     {
//         metric,
//         value,
//         display,
//         weight
//     }
// ]
// ==========================================================

function updateScoreBreakdown(data) {

    const breakdown =
        safeArray(
            data.score_breakdown
        );

    const possibleContainers = [
        "scoreBreakdown",
        "breakdownList",
        "performanceBreakdown"
    ];

    let container = null;

    for (
        const id of possibleContainers
    ) {

        container =
            document.getElementById(
                id
            );

        if (container) {
            break;
        }

    }

    if (!container) {
        return;
    }

    container.innerHTML = "";

    if (breakdown.length === 0) {

        container.innerHTML = `
            <div class="empty-state">
                No score breakdown available.
            </div>
        `;

        return;

    }

    breakdown.forEach(
        item => {

            item =
                safeObject(
                    item
                );

            const value =
                safeNumber(
                    item.value
                );

            const weight =
                safeNumber(
                    item.weight
                );

            const row =
                document.createElement(
                    "div"
                );

            row.className =
                "score-breakdown-row";

            row.innerHTML = `

                <div class="breakdown-header">

                    <span>
                        ${escapeHTML(
                            item.metric ||
                            "Metric"
                        )}
                    </span>

                    <strong>
                        ${escapeHTML(
                            item.display ||
                            `${value.toFixed(1)}%`
                        )}
                    </strong>

                </div>

                <div class="breakdown-bar">

                    <span
                        style="
                            width:${Math.max(
                                0,
                                Math.min(
                                    100,
                                    value
                                )
                            )}%;
                        "
                    ></span>

                </div>

                <small>
                    Weight: ${weight}%
                </small>

            `;

            container.appendChild(
                row
            );

        }
    );

}


// ==========================================================
// INSIGHTS
// ==========================================================
//
// Actual backend:
//
// [
//     {
//         type,
//         title,
//         message
//     }
// ]
// ==========================================================

function updateInsights(data) {

    const container =
        document.getElementById(
            "alerts"
        );

    if (!container) {
        return;
    }

    const insights =
        safeArray(
            data.insights
        );

    container.innerHTML = "";

    if (insights.length === 0) {

        container.innerHTML = `

            <div class="alert">

                <span
                    class="alert-icon alert-success"
                >
                    ✓
                </span>

                <span>
                    No performance insights available.
                </span>

            </div>

        `;

        return;

    }

    insights.forEach(
        insight => {

            insight =
                safeObject(
                    insight
                );

            const type =
                String(
                    insight.type ||
                    "info"
                )
                .trim()
                .toLowerCase();

            let icon =
                "ℹ";

            let iconClass =
                "alert-info";

            if (
                type === "success"
            ) {

                icon =
                    "✓";

                iconClass =
                    "alert-success";

            }
            else if (
                type === "warning"
            ) {

                icon =
                    "⚠";

                iconClass =
                    "alert-warning";

            }
            else if (
                type === "critical" ||
                type === "danger"
            ) {

                icon =
                    "!";

                iconClass =
                    "alert-critical";

            }

            const row =
                document.createElement(
                    "div"
                );

            row.className =
                "alert";

            row.innerHTML = `

                <span
                    class="alert-icon ${iconClass}"
                >
                    ${icon}
                </span>

                <span>

                    <strong>
                        ${escapeHTML(
                            insight.title ||
                            "Performance Insight"
                        )}
                    </strong>

                    <br>

                    ${escapeHTML(
                        insight.message ||
                        ""
                    )}

                </span>

            `;

            container.appendChild(
                row
            );

        }
    );

}


// ==========================================================
// PERFORMANCE TREND CHART
// ==========================================================
//
// Actual backend:
//
// performance_trend:
// {
//     labels,
//     delivery,
//     quality,
//     fulfillment,
//     overall
// }
//
// IMPORTANT:
// There is NO "service" or "compliance" trend
// in build_performance_report().
// ==========================================================

function updatePerformanceChart(data) {

    const trend =
        safeObject(
            data.performance_trend
        );

    const labels =
        safeArray(
            trend.labels
        );

    const delivery =
        normalizeChartArray(
            trend.delivery,
            labels.length
        );

    const quality =
        normalizeChartArray(
            trend.quality,
            labels.length
        );

    const fulfillment =
        normalizeChartArray(
            trend.fulfillment,
            labels.length
        );

    const overall =
        normalizeChartArray(
            trend.overall,
            labels.length
        );

    const canvas =
        document.getElementById(
            "performanceChart"
        );

    if (!canvas) {
        return;
    }

    if (
        typeof Chart ===
        "undefined"
    ) {

        console.warn(
            "Chart.js is not loaded."
        );

        return;

    }

    if (performanceChart) {

        performanceChart.destroy();

        performanceChart =
            null;

    }

    const ctx =
        canvas.getContext(
            "2d"
        );

    if (!ctx) {
        return;
    }

    performanceChart =
        new Chart(
            ctx,
            {

                type: "line",

                data: {

                    labels,

                    datasets: [

                        {
                            label:
                                "Delivery",

                            data:
                                delivery,

                            borderColor:
                                "#5932f4",

                            backgroundColor:
                                "transparent",

                            tension:
                                0.35,

                            borderWidth:
                                2,

                            spanGaps:
                                true
                        },

                        {
                            label:
                                "Quality",

                            data:
                                quality,

                            borderColor:
                                "#14a879",

                            backgroundColor:
                                "transparent",

                            tension:
                                0.35,

                            borderWidth:
                                2,

                            spanGaps:
                                true
                        },

                        {
                            label:
                                "Fulfillment",

                            data:
                                fulfillment,

                            borderColor:
                                "#2582ee",

                            backgroundColor:
                                "transparent",

                            tension:
                                0.35,

                            borderWidth:
                                2,

                            spanGaps:
                                true
                        },

                        {
                            label:
                                "Overall",

                            data:
                                overall,

                            borderColor:
                                "#f17b32",

                            backgroundColor:
                                "transparent",

                            tension:
                                0.35,

                            borderWidth:
                                2,

                            spanGaps:
                                true
                        }

                    ]

                },

                options: {

                    responsive: true,

                    maintainAspectRatio:
                        false,

                    interaction: {

                        intersect:
                            false,

                        mode:
                            "index"

                    },

                    plugins: {

                        legend: {

                            display:
                                false

                        },

                        tooltip: {

                            callbacks: {

                                label:
                                    function(
                                        context
                                    ) {

                                        const value =
                                            context.parsed.y;

                                        if (
                                            value === null ||
                                            value === undefined
                                        ) {

                                            return (
                                                `${context.dataset.label}: —`
                                            );

                                        }

                                        return (
                                            `${context.dataset.label}: ${Number(value).toFixed(1)}%`
                                        );

                                    }

                            }

                        }

                    },

                    scales: {

                        y: {

                            beginAtZero:
                                true,

                            max:
                                100,

                            ticks: {

                                callback:
                                    function(value) {
                                        return value + "%";
                                    },

                                font: {
                                    size: 9
                                }

                            },

                            grid: {

                                color:
                                    "#edf0f5"

                            }

                        },

                        x: {

                            ticks: {

                                font: {
                                    size: 9
                                }

                            },

                            grid: {

                                display:
                                    false

                            }

                        }

                    }

                }

            }
        );

}


// ==========================================================
// NORMALIZE CHART ARRAY
// ==========================================================

function normalizeChartArray(
    value,
    length
) {

    const array =
        safeArray(value);

    if (length <= 0) {
        return array;
    }

    return Array.from(
        {
            length
        },
        (
            _,
            index
        ) => {

            if (
                array[index] ===
                null ||
                array[index] ===
                undefined
            ) {

                return null;

            }

            return safeNumber(
                array[index]
            );

        }
    );

}


// ==========================================================
// SPEND CHART
// ==========================================================
//
// IMPORTANT:
//
// The performance endpoint DOES NOT return
// procurement_analytics.
//
// Therefore this function does NOT fabricate
// spend data.
//
// If your HTML has spendChart, it will display
// a simple empty state instead of crashing.
//
// The separate procurement_dashboard() returns:
// monthly_spend:
// [
//     {
//         month,
//         month_number,
//         total_spend
//     }
// ]
// but that endpoint is the Procurement Manager
// dashboard and is protected by Procurement Manager
// authentication, so it should not be called here
// just to populate this admin performance report.
// ==========================================================

function updateSpendChart(data) {

    const canvas =
        document.getElementById(
            "spendChart"
        );

    if (!canvas) {
        return;
    }

    if (spendChart) {

        spendChart.destroy();

        spendChart =
            null;

    }

    const parent =
        canvas.parentElement;

    if (
        parent &&
        !parent.querySelector(
            ".performance-spend-empty"
        )
    ) {

        const message =
            document.createElement(
                "div"
            );

        message.className =
            "performance-spend-empty empty-state";

        message.textContent =
            "Procurement spend data is not included in the Performance Reports API.";

        parent.appendChild(
            message
        );

    }

}


// ==========================================================
// UPDATE DATE RANGE
// ==========================================================

function updateDateRange(data) {

    const range =
        safeObject(
            data.date_range
        );

    const fromDate =
        range.from_date;

    const toDate =
        range.to_date;

    const text =
        fromDate && toDate
            ? `${formatDate(fromDate)} - ${formatDate(toDate)}`
            : "";

    setText(
        "dateRange",
        text
    );

    setText(
        "reportDateRange",
        text
    );

}


// ==========================================================
// FOOTER
// ==========================================================

function updateFooter(data) {

    const kpis =
        safeObject(
            data.kpis
        );

    setText(
        "footerVendorCount",
        safeNumber(
            kpis.total_vendors
        ).toLocaleString()
    );

    setText(
        "lastUpdated",
        new Date().toLocaleString(
            "en-IN"
        )
    );

}


// ==========================================================
// LOADING STATE
// ==========================================================

function setLoadingState(
    loading
) {

    const button =
        document.getElementById(
            "refreshButton"
        );

    if (!button) {
        return;
    }

    if (loading) {

        button.disabled =
            true;

        button.dataset.originalText =
            button.textContent;

        button.textContent =
            "Refreshing...";

    }
    else {

        button.disabled =
            false;

        if (
            button.dataset.originalText
        ) {

            button.textContent =
                button.dataset.originalText;

        }

    }

}


// ==========================================================
// REFRESH BUTTON
// ==========================================================

function initializeRefreshButton() {

    const button =
        document.getElementById(
            "refreshButton"
        );

    if (!button) {
        return;
    }

    button.addEventListener(
        "click",
        function(event) {

            event.preventDefault();

            loadDashboard();

        }
    );

}


// ==========================================================
// FILTER LISTENERS
// ==========================================================

function initializeFilters() {

    const filterIds = [
        "fromDate",
        "toDate",
        "startDate",
        "endDate",
        "categoryFilter",
        "category",
        "categorySelect",
        "vendorFilter",
        "vendorSelect",
        "vendorId"
    ];

    filterIds.forEach(
        id => {

            const element =
                document.getElementById(
                    id
                );

            if (!element) {
                return;
            }

            element.addEventListener(
                "change",
                function() {

                    loadDashboard();

                }
            );

        }
    );

}


// ==========================================================
// TABS
// ==========================================================

function initializeTabs() {

    document
        .querySelectorAll(
            ".tab"
        )
        .forEach(
            tab => {

                tab.addEventListener(
                    "click",
                    function(event) {

                        event.preventDefault();

                        document
                            .querySelectorAll(
                                ".tab"
                            )
                            .forEach(
                                item =>
                                    item.classList
                                        .remove(
                                            "active"
                                        )
                            );

                        this.classList.add(
                            "active"
                        );

                        const selected =
                            this.dataset.tab ||
                            this.getAttribute(
                                "data-tab"
                            ) ||
                            this.textContent
                                .trim();

                        console.log(
                            "Selected analytics tab:",
                            selected
                        );

                    }
                );

            }
        );

}


// ==========================================================
// AUTO REFRESH
// ==========================================================

let autoRefreshTimer =
    null;

function initializeAutoRefresh() {

    if (autoRefreshTimer) {

        clearInterval(
            autoRefreshTimer
        );

    }

    autoRefreshTimer =
        setInterval(
            function() {

                loadDashboard();

            },
            5 * 60 * 1000
        );

}


// ==========================================================
// ERROR
// ==========================================================

function showError(message) {

    console.error(
        "VendorIQ Performance Analytics:",
        message
    );

    const container =
        document.getElementById(
            "alerts"
        );

    if (container) {

        container.innerHTML = `

            <div class="alert">

                <span
                    class="alert-icon alert-critical"
                >
                    !
                </span>

                <span>
                    ${escapeHTML(
                        message ||
                        "Unable to load performance analytics."
                    )}
                </span>

            </div>

        `;

    }

    const errorElement =
        document.getElementById(
            "errorMessage"
        );

    if (errorElement) {

        errorElement.textContent =
            message ||
            "Unable to load performance analytics.";

        errorElement.style.display =
            "";

    }

}


// ==========================================================
// CLEAR ERROR
// ==========================================================

function clearError() {

    const errorElement =
        document.getElementById(
            "errorMessage"
        );

    if (errorElement) {

        errorElement.textContent =
            "";

        errorElement.style.display =
            "none";

    }

}


// ==========================================================
// ADMIN PROFILE NAVIGATION
// ==========================================================

function openAdminProfile() {

    window.location.href =
        "/admin/profile";

}


// ==========================================================
// UPDATE HEADER
// ==========================================================

function updateHeader(user) {

    user =
        safeObject(
            user
        );

    const name =
        user.name ||
        user.full_name ||
        user.fullname ||
        user.username ||
        "Admin User";

    const email =
        user.email ||
        "";

    const role =
        user.role ||
        "Administrator";

    setText(
        "headerAdminName",
        name
    );

    setText(
        "headerAdminRole",
        role
    );

    setText(
        "sidebarAdminName",
        name
    );

    setText(
        "sidebarAdminEmail",
        email
    );

}


// ==========================================================
// LOAD ADMIN PROFILE
// ==========================================================
//
// Router confirms:
//
// GET /adminprofile
//
// returns:
// id
// name
// email
// mobile
// gender
// address
// active
// role
// last_login
// created_at
// ==========================================================

async function loadAdminProfile() {

    try {

        const data =
            await apiFetch(
                `${API}/adminprofile`
            );

        console.log(
            "Admin profile:",
            data
        );

        updateHeader(
            data
        );

    }
    catch (error) {

        console.error(
            "Unable to load admin profile:",
            error
        );

        // Do not block the performance
        // dashboard if only the profile
        // endpoint fails.

        updateHeader(
            {}
        );

    }

}


// ==========================================================
// LOGOUT
// ==========================================================

function logoutAdmin() {

    const keys = [
        "access_token",
        "token",
        "accessToken",
        "jwt_token",
        "user",
        "currentUser"
    ];

    keys.forEach(
        key => {

            localStorage.removeItem(
                key
            );

            sessionStorage.removeItem(
                key
            );

        }
    );

    window.location.href =
        "/login";

}


// ==========================================================
// GLOBAL FUNCTIONS
// ==========================================================
//
// Keeps compatibility with HTML such as:
//
// onclick="loadDashboard()"
// onclick="openAdminProfile()"
// onclick="logoutAdmin()"
// ==========================================================

window.loadDashboard =
    loadDashboard;

window.openAdminProfile =
    openAdminProfile;

window.loadAdminProfile =
    loadAdminProfile;

window.logoutAdmin =
    logoutAdmin;

window.refreshDashboard =
    loadDashboard;


// ==========================================================
// INITIALIZE
// ==========================================================

document.addEventListener(
    "DOMContentLoaded",
    async function() {

        console.log(
            "Initializing VendorIQ Performance Analytics..."
        );

        initializeRefreshButton();

        initializeFilters();

        initializeTabs();

        initializeAutoRefresh();

        await Promise.allSettled([
            loadAdminProfile(),
            loadDashboard()
        ]);

    }
);